// Testes do módulo AGENTE DE ANÁLISE DE DOCUMENTOS (extração, checklist, conflitos, instituição simulada, equivalência, críticos, bloqueios, LGPD, painel, seed).
// Uso:  DATABASE_URL=postgresql://usuario:senha@127.0.0.1:5432/banco_local npx tsx scripts/e2e/analise-docs.ts
// Requer Postgres LOCAL com o schema aplicado (prisma db push). Não usa internet nem chaves externas. NUNCA aponte para banco remoto/edutest.
import { setup, check, summary, prisma, fails, Actor } from './qa5-lib'
import {
  anosEntre, avaliarDocumento, compararDocumentos, extrairCampos, levenshtein, mascararCpfDoc, mascararNomeDoc, montarChecklist, normNome, parseData, pontuar, resultadoDe,
  similaridadeNome, similaridadeTexto, sinaisAdulteracao, slaDoCaso, sugerirEquivalencias, tokens, validarCnpj, validarCpf,
} from '../../src/modules/analise-docs/logic'
import { lerArquivo } from '../../src/modules/analise-docs/provedores'
import { cifrar, decifrar } from '../../src/modules/seguranca/cripto'
import { cpfFicticio, fmtCpf, pdfFicticio, seedAnaliseDocs, textoHistorico } from '../seeds/analise-docs'

const secao = (t: string) => console.log(`\n== ${t}`)
const DAY = 86_400_000
const ymd = (n: number) => new Date(Date.now() + n * DAY).toISOString().slice(0, 10)
const br = (iso: string) => iso.split('-').reverse().join('/')
const A = '/edu/analise-docs'
const por = (arr: any[], regra: string) => (arr || []).filter((a) => a.regra === regra)

async function main() {
  // ---------------------------------------------------------------- unidades puras
  secao('Funções puras: CPF/CNPJ, nomes e datas')
  const cpf1 = cpfFicticio(1), cpf2 = cpfFicticio(2)
  check('cpfFicticio gera CPF válido', validarCpf(cpf1) && validarCpf(cpf2) && cpf1 !== cpf2)
  check('CPF com dígito errado é inválido', !validarCpf(cpf1.slice(0, 10) + String((Number(cpf1[10]) + 1) % 10)))
  check('CPF com dígitos repetidos é inválido', !validarCpf('11111111111') && !validarCpf('00000000000'))
  check('CPF aceita máscara', validarCpf(fmtCpf(cpf1)))
  check('CPF tamanho errado', !validarCpf('123') && !validarCpf(''))
  check('CNPJ válido conhecido', validarCnpj('11.222.333/0001-81'))
  check('CNPJ inválido', !validarCnpj('12.345.678/0001-00') && !validarCnpj('11111111111111') && !validarCnpj('123'))
  check('máscara de CPF', mascararCpfDoc(cpf1) === `***.${cpf1.slice(3, 6)}.***-${cpf1.slice(9)}` && !mascararCpfDoc(cpf1).includes(cpf1.slice(0, 3) + '.'))
  check('máscara de nome', mascararNomeDoc('Maria José da Silva Santos') === 'Maria J. da S. S.' && mascararNomeDoc('') === '')
  check('normNome remove acento e partículas', normNome('José  da Silva-Ávila') === 'JOSE SILVA AVILA')
  check('similaridade de nome idêntica (acentos)', similaridadeNome('José Álvares', 'JOSE ALVARES') === 1)
  check('similaridade: iniciais no meio', similaridadeNome('Maria J Silva', 'Maria José Silva') >= 0.9)
  check('similaridade: nomes diferentes', similaridadeNome('Carlos Pereira Lima', 'Ana Beatriz Torres') < 0.5)
  check('levenshtein', levenshtein('casa', 'caso') === 1 && levenshtein('', 'abc') === 3 && levenshtein('a', 'a') === 0)
  check('parseData formatos', parseData('05/03/2020') === '2020-03-05' && parseData('2020-03-05') === '2020-03-05' && parseData('05-03-2020') === '2020-03-05')
  check('parseData rejeita data impossível', parseData('31/02/2020') === undefined && parseData('xx') === undefined && parseData(null) === undefined)
  check('anosEntre', Math.round(anosEntre('2000-01-01', '2020-01-01')) === 20)

  secao('Extração de campos a partir de texto')
  const txt = textoHistorico({ nome: 'Ana Clara Dias', cpf: cpf1, nasc: '2000-02-10', inst: 'Universidade Federal do Vale Azul', cod: '1001', curso: 'Odontologia', total: 140, emissao: '2026-01-10', conclusao: '2025-12-20', inicio: '2021-02-01', assin: true, qr: true, uf: 'SP', disc: [['Anatomia Humana', 80, 8.5, 'APROVADO', 2023], ['Histologia', 60, 7, 'APROVADO', 2023]], ementas: { 'Anatomia Humana': 'Estudo do corpo humano.' } })
  const c = extrairCampos(txt)
  check('extrai nome', c.nome === 'Ana Clara Dias')
  check('extrai CPF só dígitos', c.cpf === cpf1)
  check('extrai nascimento ISO', c.dataNascimento === '2000-02-10')
  check('extrai instituição e código', c.instituicao === 'Universidade Federal do Vale Azul' && c.codigoIes === '1001')
  check('extrai curso, UF e carga total', c.curso === 'Odontologia' && c.uf === 'SP' && c.cargaHorariaTotal === 140)
  check('extrai datas', c.dataEmissao === '2026-01-10' && c.dataConclusao === '2025-12-20' && c.dataInicio === '2021-02-01')
  check('extrai assinatura digital e QR', c.assinaturaDigital === true && c.qrCode === true)
  check('extrai disciplinas com nota e ano', c.disciplinas?.length === 2 && c.disciplinas[0].cargaHoraria === 80 && c.disciplinas[0].nota === 8.5 && c.disciplinas[0].ano === 2023 && c.disciplinas[0].situacao === 'APROVADO')
  check('extrai ementa da disciplina', c.disciplinas?.[0].ementa === 'Estudo do corpo humano.' && !c.disciplinas?.[1].ementa)
  check('assinatura ausente explícita', extrairCampos('Nome: X Y\nAssinatura: ausente').assinaturaDigital === false)
  const nf = extrairCampos('Emitente: Papelaria Central\nCNPJ: 11.222.333/0001-81\nNota fiscal nº 4455\nValor total: R$ 1.234,56\nData de emissão: 01/02/2026\nChave de acesso: ' + '1'.repeat(44))
  check('extrai nota fiscal', nf.emitente === 'Papelaria Central' && nf.emitenteCnpj === '11222333000181' && nf.valor === 1234.56 && nf.numeroDocumento === '4455' && nf.chaveAcesso?.length === 44)

  secao('Checklist e regras por documento')
  const ck = montarChecklist('HISTORICO_ESCOLAR', { nome: 'A B' })
  check('checklist marca itens ausentes', ck.filter((i) => !i.ok && i.obrigatorio).length >= 5 && ck.find((i) => i.campo === 'nome')?.ok === true)
  check('checklist: CPF do histórico é opcional', ck.find((i) => i.campo === 'cpf')?.obrigatorio === false)
  const completo = avaliarDocumento('HISTORICO_ESCOLAR', c, undefined, {})
  check('documento completo e coerente: sem achados ALTA/CRITICA', !completo.some((a) => ['ALTA', 'CRITICA'].includes(a.gravidade)), completo.map((a) => a.regra))
  const ausente = avaliarDocumento('DIPLOMA', { nome: 'Fulano de Tal' }, undefined, {})
  check('diploma incompleto gera campos ausentes e falta de assinatura/QR', por(ausente, 'CAMPO_OBRIGATORIO_AUSENTE').length >= 4 && por(ausente, 'ASSINATURA_QR_AUSENTE').length === 1)
  check('CPF inválido detectado', por(avaliarDocumento('RG_CPF', { nome: 'A B', cpf: '12345678900', dataNascimento: '2000-01-01' }), 'CPF_INVALIDO').length === 1)
  check('CNPJ inválido detectado', por(avaliarDocumento('NOTA_FISCAL', { emitente: 'X', emitenteCnpj: '12345678000100', numeroDocumento: '1', valor: 10, dataEmissao: '2026-01-01' }), 'CNPJ_INVALIDO').length === 1)
  check('chave de acesso com tamanho errado', por(avaliarDocumento('NOTA_FISCAL', { emitente: 'X', emitenteCnpj: '11222333000181', numeroDocumento: '1', valor: 10, dataEmissao: '2026-01-01', chaveAcesso: '123' }), 'CHAVE_ACESSO_INVALIDA').length === 1)
  check('data futura detectada', por(avaliarDocumento('DECLARACAO', { nome: 'A B', instituicao: 'X', dataEmissao: ymd(30), assinaturaDigital: true }), 'DATA_FUTURA').length === 1)
  check('conclusão antes do início', por(avaliarDocumento('DIPLOMA', { dataInicio: ymd(-100), dataConclusao: ymd(-300) }), 'DATAS_INCOERENTES').length >= 1)
  check('emissão antes da conclusão', por(avaliarDocumento('DIPLOMA', { dataConclusao: ymd(-10), dataEmissao: ymd(-50) }), 'DATAS_INCOERENTES').length >= 1)
  check('idade incompatível com a conclusão', por(avaliarDocumento('HISTORICO_ENSINO_MEDIO', { dataNascimento: '2015-01-01', dataConclusao: '2024-12-01' }), 'IDADE_INCOMPATIVEL').length === 1)
  check('certidão vencida', por(avaliarDocumento('CERTIDAO', { emitente: 'RFB', nome: 'X', dataEmissao: ymd(-100), validade: ymd(-5) }), 'DOCUMENTO_VENCIDO').length === 1)
  check('vigência incoerente', por(avaliarDocumento('CONTRATO', { partes: 'A / B', vigenciaInicio: ymd(10), vigenciaFim: ymd(-10), assinaturaDigital: true }), 'DATAS_INCOERENTES').length === 1)
  const carga = avaliarDocumento('HISTORICO_ESCOLAR', { ...c, cargaHorariaTotal: 400 })
  check('carga horária que não fecha', por(carga, 'CARGA_HORARIA_NAO_FECHA').length === 1 && por(carga, 'CARGA_HORARIA_NAO_FECHA')[0].gravidade === 'ALTA')
  check('carga horária com pequena diferença passa (<2%)', por(avaliarDocumento('HISTORICO_ESCOLAR', { ...c, cargaHorariaTotal: 141 }), 'CARGA_HORARIA_NAO_FECHA').length === 0)
  check('nota fora da escala', por(avaliarDocumento('HISTORICO_ESCOLAR', { ...c, disciplinas: [{ nome: 'X', cargaHoraria: 140, nota: 12, situacao: 'APROVADO' }] }), 'NOTA_INVALIDA').length === 1)
  check('situação incoerente com a nota', por(avaliarDocumento('HISTORICO_ESCOLAR', { ...c, disciplinas: [{ nome: 'X', cargaHoraria: 140, nota: 3, situacao: 'APROVADO' }, { nome: 'Y', cargaHoraria: 0, nota: 9, situacao: 'REPROVADO' }] }), 'SITUACAO_INCOERENTE').length === 2)
  check('disciplina duplicada', por(avaliarDocumento('HISTORICO_ESCOLAR', { ...c, disciplinas: [{ nome: 'Anatomia', cargaHoraria: 70, nota: 7, situacao: 'APROVADO' }, { nome: 'anatomia', cargaHoraria: 70, nota: 7, situacao: 'APROVADO' }] }), 'DISCIPLINA_DUPLICADA').length === 1)

  secao('Sinais de adulteração (metadados)')
  check('sem metadados: nenhum sinal', sinaisAdulteracao(undefined, {}).length === 0)
  check('software de edição é sinal (peso 1)', sinaisAdulteracao({ producer: 'Adobe Photoshop 25' }, {}).some((s) => s.sinal === 'SOFTWARE_EDICAO' && s.peso === 1))
  check('criado antes da emissão (peso 2)', sinaisAdulteracao({ criadoEm: ymd(-200) }, { dataEmissao: ymd(-10) }).some((s) => s.sinal === 'CRIADO_ANTES_DA_EMISSAO'))
  check('modificado após criação', sinaisAdulteracao({ criadoEm: ymd(-30), modificadoEm: ymd(-2) }, {}).some((s) => s.sinal === 'MODIFICADO_APOS_CRIACAO'))
  const leve = avaliarDocumento('DECLARACAO', { nome: 'A B', instituicao: 'X', dataEmissao: ymd(-3), assinaturaDigital: true }, { producer: 'GIMP' })
  check('um sinal isolado = MEDIA', por(leve, 'INDICIO_ADULTERACAO')[0]?.gravidade === 'MEDIA')
  const forte = avaliarDocumento('DECLARACAO', { nome: 'A B', instituicao: 'X', dataEmissao: ymd(-3), assinaturaDigital: true }, { producer: 'Photoshop', camposSobrepostos: true })
  check('vários sinais = CRITICA', por(forte, 'INDICIO_ADULTERACAO')[0]?.gravidade === 'CRITICA')
  check('assinatura presente porém inválida = CRITICA', por(avaliarDocumento('CONTRATO', { partes: 'A / B', vigenciaInicio: ymd(-5), assinaturaDigital: true }, { assinaturaPresente: true, assinaturaValida: false }), 'INDICIO_ADULTERACAO')[0]?.gravidade === 'CRITICA')
  check('QR que não confere = CRITICA', por(avaliarDocumento('DIPLOMA', { ...extrairCampos(txt), qrCode: true }, { qrConfere: false }), 'INDICIO_ADULTERACAO')[0]?.gravidade === 'CRITICA')

  secao('Conflitos entre documentos e com o cadastro')
  const base = (nome: string, cpf?: string, nasc?: string) => ({ nome, cpf, dataNascimento: nasc })
  check('documentos coerentes: sem conflito', compararDocumentos([{ idx: 0, tipo: 'RG_CPF', campos: base('Ana Dias', cpf1, '2000-01-01') }, { idx: 1, tipo: 'DIPLOMA', campos: base('ANA DIAS', cpf1, '2000-01-01') }]).length === 0)
  const cCpf = compararDocumentos([{ idx: 0, tipo: 'RG_CPF', campos: base('Ana Dias', cpf1) }, { idx: 1, tipo: 'DIPLOMA', campos: base('Ana Dias', cpf2) }])
  check('CPF diferente = CRITICA', por(cCpf, 'CONFLITO_CPF')[0]?.gravidade === 'CRITICA')
  check('evidência do conflito traz CPF mascarado', !JSON.stringify(cCpf).includes(cpf1) && JSON.stringify(cCpf).includes(mascararCpfDoc(cpf1)))
  const cNome = compararDocumentos([{ idx: 0, tipo: 'RG_CPF', campos: base('Ana Dias') }, { idx: 1, tipo: 'DIPLOMA', campos: base('Bruno Costa Lima') }])
  check('nome muito diferente = ALTA', por(cNome, 'CONFLITO_NOME')[0]?.gravidade === 'ALTA')
  check('nome + CPF diferentes = CRITICA no nome', por(compararDocumentos([{ idx: 0, tipo: 'RG_CPF', campos: base('Ana Dias', cpf1) }, { idx: 1, tipo: 'DIPLOMA', campos: base('Bruno Costa Lima', cpf2) }]), 'CONFLITO_NOME')[0]?.gravidade === 'CRITICA')
  check('grafia levemente diferente = BAIXA', por(compararDocumentos([{ idx: 0, tipo: 'RG_CPF', campos: base('Ana Claudia Dias') }, { idx: 1, tipo: 'DIPLOMA', campos: base('Ana Claudia Dyas') }]), 'NOME_GRAFIA_DIFERENTE')[0]?.gravidade === 'BAIXA')
  check('nascimento diferente = ALTA', por(compararDocumentos([{ idx: 0, tipo: 'RG_CPF', campos: base('Ana', undefined, '2000-01-01') }, { idx: 1, tipo: 'DIPLOMA', campos: base('Ana', undefined, '2000-02-01') }]), 'CONFLITO_NASCIMENTO')[0]?.gravidade === 'ALTA')
  check('cadastro do aluno diverge', por(compararDocumentos([{ idx: 0, tipo: 'RG_CPF', campos: base('Ana Dias', cpf1) }], { nome: 'Carla Mendes', cpf: cpf2 }), 'CONFLITO_CPF').length === 1)

  secao('Pontuação, SLA e tokens')
  check('pontuação soma por gravidade e limita a 100', pontuar([{ gravidade: 'BAIXA' }, { gravidade: 'MEDIA' }]) === 13 && pontuar([{ gravidade: 'CRITICA' }, { gravidade: 'CRITICA' }]) === 100)
  check('pontuação ignora achados resolvidos', pontuar([{ gravidade: 'ALTA', resolvido: true }, { gravidade: 'BAIXA' }]) === 3)
  check('resultado OK/ATENCAO/CRITICO', resultadoDe([{ gravidade: 'INFO' }]) === 'OK' && resultadoDe([{ gravidade: 'MEDIA' }]) === 'ATENCAO' && resultadoDe([{ gravidade: 'CRITICA' }, { gravidade: 'BAIXA' }]) === 'CRITICO')
  const b0 = new Date('2026-01-01T00:00:00Z')
  check('SLA normal e crítico', slaDoCaso(b0, { slaHoras: 48, slaCriticoHoras: 4 }, false).getTime() - b0.getTime() === 48 * 3_600_000 && slaDoCaso(b0, { slaHoras: 48, slaCriticoHoras: 4 }, true).getTime() - b0.getTime() === 4 * 3_600_000)
  check('tokens ignoram acentos e stopwords', tokens('Introdução à Anatomia do Corpo').includes('ANATO') && !tokens('Introdução à Anatomia').includes('DE'))
  check('similaridade de texto', similaridadeTexto('Anatomia Humana', 'Anatomia Humana I') >= 0.8 && similaridadeTexto('Direito Civil', 'Bioquímica') === 0)

  secao('Equivalência (função pura)')
  const dest = [
    { id: 'd1', nome: 'Anatomia Humana', cargaHoraria: 80, ementa: 'Estudo da anatomia sistêmica do corpo humano' },
    { id: 'd2', nome: 'Histologia e Embriologia', cargaHoraria: 60 },
    { id: 'd3', nome: 'Bioquímica Oral', cargaHoraria: 60 },
    { id: 'd4', nome: 'Dentística II', cargaHoraria: 80, preRequisitos: ['d5'] },
    { id: 'd5', nome: 'Dentística I', cargaHoraria: 80 },
  ]
  const cfg = { percentualAproveitamento: 75, similaridadeMinima: 55, validadeAproveitamentoAnos: 10, anoAtual: 2026 }
  const eq = sugerirEquivalencias([
    { nome: 'Anatomia Humana Geral', cargaHoraria: 80, nota: 8, situacao: 'APROVADO', ano: 2024, ementa: 'Estudo da anatomia sistêmica do corpo humano' },
    { nome: 'Histologia', cargaHoraria: 40, nota: 7, situacao: 'APROVADO', ano: 2024 },
    { nome: 'Bioquímica Oral', cargaHoraria: 60, nota: 7, situacao: 'REPROVADO', ano: 2024 },
    { nome: 'Dentística II', cargaHoraria: 80, nota: 8, situacao: 'APROVADO', ano: 2010 },
    { nome: 'Cálculo Diferencial', cargaHoraria: 60, nota: 9, situacao: 'APROVADO', ano: 2024 },
  ], dest, cfg, [])
  const por2 = (n: string) => eq.find((e) => e.origem.nome === n)!
  check('equivalência plena (carga >= 75%)', por2('Anatomia Humana Geral').sugestao === 'EQUIVALENCIA' && por2('Anatomia Humana Geral').destino?.id === 'd1')
  check('carga insuficiente => dispensa parcial + aviso', por2('Histologia').sugestao === 'DISPENSA_PARCIAL' && por2('Histologia').avisos.some((a) => a.tipo === 'CARGA_INSUFICIENTE'))
  check('reprovação na origem => não equivalente + aviso', por2('Bioquímica Oral').sugestao === 'NAO_EQUIVALENTE' && por2('Bioquímica Oral').avisos.some((a) => a.tipo === 'REPROVACAO'))
  check('prazo de validade excedido', por2('Dentística II').avisos.some((a) => a.tipo === 'PRAZO_VALIDADE'))
  check('pré-requisito pendente', por2('Dentística II').avisos.some((a) => a.tipo === 'PRE_REQUISITO'))
  check('sem correspondente', por2('Cálculo Diferencial').sugestao === 'NAO_EQUIVALENTE' && !por2('Cálculo Diferencial').destino)
  const eq2 = sugerirEquivalencias([{ nome: 'Dentística II', cargaHoraria: 80, nota: 8, situacao: 'APROVADO', ano: 2025 }], dest, cfg, [{ disciplineId: 'd5', situacao: 'APROVADO' }])
  check('pré-requisito cumprido no histórico não gera aviso', !eq2[0].avisos.some((a) => a.tipo === 'PRE_REQUISITO'))
  const eq3 = sugerirEquivalencias([{ nome: 'Anatomia Humana', cargaHoraria: 80, nota: 8, situacao: 'APROVADO', ano: 2025 }], dest, cfg, [{ disciplineId: 'd1', situacao: 'EM CURSO' }])
  check('disciplina em curso no histórico local', eq3[0].avisos.some((a) => a.tipo === 'EM_CURSO'))
  const eq4 = sugerirEquivalencias([{ nome: 'Anatomia Humana', cargaHoraria: 80, nota: 8, situacao: 'APROVADO', ano: 2025 }], dest, { ...cfg, percentualAproveitamento: 100 }, [{ disciplineId: 'd1', situacao: 'APROVADO' }])
  check('já aprovada no histórico local', eq4[0].avisos.some((a) => a.tipo === 'JA_CURSADA'))
  const eq5 = sugerirEquivalencias([{ nome: 'Anatomia Humana', cargaHoraria: 60, nota: 8, situacao: 'APROVADO', ano: 2025 }], dest, { ...cfg, percentualAproveitamento: 70 })
  check('percentual configurável muda o resultado (60/80 = 75%)', eq5[0].sugestao === 'EQUIVALENCIA' && sugerirEquivalencias([{ nome: 'Anatomia Humana', cargaHoraria: 60, nota: 8, situacao: 'APROVADO', ano: 2025 }], dest, { ...cfg, percentualAproveitamento: 90 })[0].sugestao === 'DISPENSA_PARCIAL')
  const eq6 = sugerirEquivalencias([{ nome: 'Anatomia Humana', cargaHoraria: 80, nota: 8, situacao: 'APROVADO', ano: 2025 }, { nome: 'Anatomia Humana Básica', cargaHoraria: 80, nota: 7, situacao: 'APROVADO', ano: 2025 }], dest, cfg)
  check('destino usado uma só vez', eq6.filter((e) => e.destino?.id === 'd1').length === 1 && eq6.some((e) => e.avisos.some((a) => a.tipo === 'DESTINO_DUPLICADO')))

  secao('Leitura de arquivo (texto/PDF) e cifra')
  const pdf = pdfFicticio(['Nome: Teste Silva', 'Instituição: Universidade X'], { producer: 'Canva', creator: 'Canva', criado: ymd(-20), modificado: ymd(-1), assinado: true })
  const lido = lerArquivo({ nome: 'a.pdf', dataUrl: pdf })!
  check('PDF: hash, tamanho e modo de texto', !!lido.hash && lido.hash.length === 64 && lido.tamanho! > 50 && lido.modo === 'PDF_TEXTO')
  check('PDF: texto extraído', (lido.texto || '').includes('Nome: Teste Silva'))
  check('PDF: metadados Producer/Creator/datas', lido.metadados.producer === 'Canva' && lido.metadados.criadoEm === ymd(-20) && lido.metadados.modificadoEm === ymd(-1))
  check('PDF: assinatura detectada', lido.metadados.assinaturaPresente === true && lido.assinaturaPdf === true)
  const lido2 = lerArquivo({ nome: 'x.txt', mime: 'text/plain', dataUrl: 'data:text/plain;base64,' + Buffer.from('Nome: Fulano').toString('base64') })!
  check('texto simples lido', lido2.modo === 'TEXTO' && lido2.texto === 'Nome: Fulano')
  check('imagem sem texto => SEM_TEXTO (sem OCR)', lerArquivo({ nome: 'f.png', mime: 'image/png', base64: Buffer.from([137, 80, 78, 71]).toString('base64') })!.modo === 'SEM_TEXTO')
  check('arquivo ilegível => null', lerArquivo({ dataUrl: 'lixo' }) === null && lerArquivo(undefined) === null)
  const cif = cifrar(JSON.stringify({ cpf: cpf1 }))
  check('cifra AES-GCM não deixa o CPF em claro e decifra', !cif.includes(cpf1) && JSON.parse(decifrar(cif)).cpf === cpf1)

  // ---------------------------------------------------------------- ambiente
  const { call, t1, t2, close, base: baseUrl } = await setup()
  const T = t1.tenantId, T2 = t2.tenantId
  const admin = await t1.mk('ADMIN'), sec = await t1.mk('SECRETARY'), coord = await t1.mk('COORDINATOR'), fin = await t1.mk('FINANCE'), legal = await t1.mk('LEGAL'), reitor = await t1.mk('RECTOR')
  const aluno: Actor = await t1.mk('STUDENT', true), prof = await t1.mk('TEACHER'), adm2 = await t1.mk('ADMISSIONS')
  const admin2 = await t2.mk('ADMIN'), sec2 = await t2.mk('SECRETARY')
  const tx = (k: string) => `${k}${Math.random().toString(36).slice(2, 6)}`

  secao('Permissões e isolamento')
  check('sem token -> 401', (await call(null, 'GET', `${A}/casos`)).status === 401)
  for (const [n, a] of [['aluno', aluno], ['professor', prof]] as const) check(`${n} não acessa o agente (403)`, (await call(a, 'GET', `${A}/painel`)).status === 403)
  check('meta para operadores', (await call(sec, 'GET', `${A}/meta`)).json?.tipos?.length >= 8)
  check('meta informa provedor simulado', (await call(sec, 'GET', `${A}/meta`)).json?.provedor?.simulado === true)
  check('secretaria só vê origem SECRETARIA', JSON.stringify((await call(sec, 'GET', `${A}/meta`)).json?.origens) === '["SECRETARIA"]')
  check('financeiro só vê origem FINANCEIRO', JSON.stringify((await call(fin, 'GET', `${A}/meta`)).json?.origens) === '["FINANCEIRO"]')
  const docOk = (nome: string, cpf: string) => ({ tipo: 'RG_CPF', texto: `Nome: ${nome}\nCPF: ${fmtCpf(cpf)}\nData de nascimento: 10/10/1999` })
  check('financeiro não cria caso da SECRETARIA (403)', (await call(fin, 'POST', `${A}/casos`, { origem: 'SECRETARIA', titulo: 'Teste financeiro', documentos: [docOk('Ana Dias', cpf1)] })).status === 403)
  check('jurídico não cria caso do FINANCEIRO (403)', (await call(legal, 'POST', `${A}/casos`, { origem: 'FINANCEIRO', titulo: 'Teste jurídico', documentos: [docOk('Ana Dias', cpf1)] })).status === 403)
  check('secretaria não cria caso do JURIDICO (403)', (await call(sec, 'POST', `${A}/casos`, { origem: 'JURIDICO', titulo: 'Teste secretaria', documentos: [docOk('Ana Dias', cpf1)] })).status === 403)
  check('payload inválido (sem documentos) -> 400', (await call(sec, 'POST', `${A}/casos`, { origem: 'SECRETARIA', titulo: 'Sem docs', documentos: [] })).status === 400)
  check('tipo de documento inválido -> 400', (await call(sec, 'POST', `${A}/casos`, { origem: 'SECRETARIA', titulo: 'Tipo ruim', documentos: [{ tipo: 'XYZ', texto: 'a' }] })).status === 400)
  check('origem inválida -> 400', (await call(sec, 'POST', `${A}/casos`, { origem: 'OUTRA', titulo: 'Origem ruim', documentos: [docOk('Ana Dias', cpf1)] })).status === 400)
  check('campos desconhecidos são rejeitados (strict)', (await call(sec, 'POST', `${A}/casos`, { origem: 'SECRETARIA', titulo: 'Campo extra', documentos: [{ tipo: 'RG_CPF', campos: { nome: 'A B', hackeado: true } }] })).status === 400)
  check('aluno de outro tenant é rejeitado', (await call(sec, 'POST', `${A}/casos`, { origem: 'SECRETARIA', titulo: 'Ref inválida', studentId: 'nao-existe', documentos: [docOk('Ana Dias', cpf1)] })).status === 400)

  // ---------------------------------------------------------------- caso conforme
  secao('Caso conforme (OK)')
  const histOk = textoHistorico({ nome: 'Camila Duarte Ferraz', cpf: cpf1, inst: 'Universidade Federal do Vale Azul', cod: '1001', curso: 'Odontologia', total: 140, inicio: ymd(-1200), conclusao: ymd(-400), emissao: ymd(-20), assin: true, qr: true, disc: [['Anatomia Humana', 80, 8.5, 'APROVADO', 2023], ['Histologia e Embriologia', 60, 7.8, 'APROVADO', 2023]] })
  const r1 = await call(sec, 'POST', `${A}/casos`, { origem: 'SECRETARIA', contexto: 'TRANSFERENCIA', titulo: 'Transferência conforme', documentos: [{ tipo: 'HISTORICO_ESCOLAR', texto: histOk }, { tipo: 'RG_CPF', texto: `Nome: Camila Duarte Ferraz\nCPF: ${fmtCpf(cpf1)}\nData de nascimento: 14/03/2001` }] })
  const ok1 = r1.json
  check('caso criado e analisado (201)', r1.status === 201 && ok1?.codigo?.startsWith('ADC-') && ok1.status === 'EM_REVISAO')
  check('resultado OK sem bloqueio', ok1.resultado === 'OK' && ok1.bloqueado === false && ok1.critico === false, { r: ok1.resultado, a: ok1.achados?.map((a: any) => a.regra) })
  check('instituição regular registrada como achado INFO', ok1.achados.some((a: any) => a.regra === 'INSTITUICAO_REGULAR' && a.gravidade === 'INFO'))
  check('consulta de instituição marcada como SIMULADA', ok1.consultas.length === 1 && ok1.consultas[0].simulada === true && ok1.consultas[0].provedor === 'SIMULADO')
  check('aviso de simulação no detalhe', /SIMULADA/.test(ok1.aviso || ''))
  check('documentos têm checklist e confiança', ok1.documentos.length === 2 && ok1.documentos.every((d: any) => Array.isArray(d.checklist) && d.confianca > 0))
  check('sujeito mascarado (sem nome completo)', ok1.sujeitoNome === 'Camila D. F.' && !JSON.stringify(ok1).includes(cpf1))
  check('resumo (laudo) em texto', /Caso ADC-/.test(ok1.resumo) && ok1.modoAnalise === 'REGRAS')
  check('permissões do caso: pode decidir', ok1.permissoes.decidir === true && ok1.permissoes.verDados === true)
  const dbDoc = await prisma.adcDocumento.findFirst({ where: { casoId: ok1.id } })
  check('dados pessoais persistidos cifrados', !!dbDoc?.dadosCif && !dbDoc.dadosCif.includes(cpf1) && !dbDoc.dadosCif.includes('Camila'))
  check('camposResumo mascarado no banco', !JSON.stringify(dbDoc?.camposResumo).includes(cpf1))
  const dec1 = await call(sec, 'POST', `${A}/casos/${ok1.id}/decisao`, { decisao: 'APROVAR', justificativa: 'Documentos conferidos.' })
  check('aprovação de caso conforme', dec1.status === 200 && dec1.json.status === 'APROVADO' && dec1.json.decididoPorNome)
  check('decidir de novo -> 409', (await call(sec, 'POST', `${A}/casos/${ok1.id}/decisao`, { decisao: 'REJEITAR', justificativa: 'Mudei de ideia agora.' })).status === 409)
  check('justificativa curta -> 400', (await call(sec, 'POST', `${A}/casos/${(await call(sec, 'POST', `${A}/casos`, { origem: 'SECRETARIA', titulo: 'Para justificativa curta', documentos: [docOk('Ana Dias', cpf1)] })).json.id}/decisao`, { decisao: 'APROVAR', justificativa: 'ok' })).status === 400)

  // ---------------------------------------------------------------- conflito grave de identidade => crítico
  secao('Crítico: conflito de identidade, aviso à reitoria/diretoria e bloqueio')
  const antesNot = await prisma.eduNotification.count({ where: { tenantId: T, templateKey: 'adc.critico' } })
  const rc = await call(sec, 'POST', `${A}/casos`, { origem: 'SECRETARIA', contexto: 'TRANSFERENCIA', titulo: 'CPF divergente', documentos: [{ tipo: 'HISTORICO_ESCOLAR', texto: textoHistorico({ nome: 'Rafael Augusto Pinheiro', cpf: cpf1, inst: 'Centro Universitário Horizonte', cod: '1002', curso: 'Odontologia', total: 60, emissao: ymd(-10), assin: true, disc: [['Anatomia', 60, 8, 'APROVADO', 2024]] }) }, { tipo: 'RG_CPF', texto: `Nome: Rodrigo Alves Macedo\nCPF: ${fmtCpf(cpf2)}\nData de nascimento: 21/11/1999` }] })
  const crit = rc.json
  check('conflito de CPF => CRITICO', crit.resultado === 'CRITICO' && crit.critico === true && por(crit.achados, 'CONFLITO_CPF')[0]?.gravidade === 'CRITICA')
  check('caso crítico fica bloqueado', crit.bloqueado === true && crit.permissoes.exigeAlcada === true)
  check('achados ordenados por gravidade (crítico primeiro)', crit.achados[0].gravidade === 'CRITICA')
  check('achado explicável: explicação, evidência e sugestão', !!crit.achados[0].explicacao && !!crit.achados[0].evidencia && !!crit.achados[0].sugestao)
  check('achado de conflito não vaza o CPF', !JSON.stringify(crit).includes(cpf1) && !JSON.stringify(crit).includes(cpf2))
  const reitorUser = await prisma.user.findUnique({ where: { id: reitor.id } })
  const notReitor = await prisma.eduNotification.findMany({ where: { tenantId: T, userId: reitor.id, templateKey: 'adc.critico', refId: crit.id } })
  check('reitor recebe notificação imediata', notReitor.length === 1 && /CRÍTICO/.test(notReitor[0].assunto || '') && !!reitorUser)
  const notCoord = await prisma.eduNotification.findMany({ where: { tenantId: T, userId: coord.id, templateKey: 'adc.critico', refId: crit.id } })
  check('diretoria do setor (coordenação) recebe notificação', notCoord.length === 1)
  check('notificação não contém dados pessoais', !notReitor[0].mensagem.includes(cpf1) && !notReitor[0].mensagem.includes('Rafael'))
  check('quantidade de notificações coerente', (await prisma.eduNotification.count({ where: { tenantId: T, templateKey: 'adc.critico' } })) - antesNot >= 2)
  const lembs = await prisma.eduReminder.findMany({ where: { tenantId: T, refType: 'AdcCaso', refId: crit.id, dedupeKey: { startsWith: 'adc:crit:' } } })
  check('lembretes críticos para RECTOR e diretoria', lembs.length === 2 && lembs.every((l) => l.severity === 'CRITICO') && lembs.some((l) => l.assigneeRole === 'RECTOR') && lembs.some((l) => l.assigneeRole === 'COORDINATOR'))
  const aud = await prisma.eduAuditEvent.findMany({ where: { tenantId: T, modulo: 'analise-docs', acao: 'CRITICO_NOTIFICADO', refId: crit.id } })
  check('trilha de auditoria do aviso crítico', aud.length === 1)
  check('evento CRITICO_NOTIFICADO no histórico', crit.eventos.some((e: any) => e.tipo === 'CRITICO_NOTIFICADO'))
  const re = await call(sec, 'POST', `${A}/casos/${crit.id}/analisar`)
  check('reanálise não duplica o aviso crítico', re.status === 200 && (await prisma.eduNotification.count({ where: { tenantId: T, userId: reitor.id, templateKey: 'adc.critico', refId: crit.id } })) === 1)

  // bloqueio no protocolo da secretaria
  const tipoReq = await prisma.secTipoRequerimento.create({ data: { tenantId: T, codigo: tx('TR'), nome: 'Transferência de curso' } })
  const proto = await prisma.secProtocolo.create({ data: { tenantId: T, numero: `2026/${Math.floor(Math.random() * 900000 + 1000)}`, ano: 2026, seq: Math.floor(Math.random() * 900000 + 1000), tipoId: tipoReq.id, assunto: 'Transferência', status: 'EM_ANALISE', prazoEm: new Date(Date.now() + 5 * DAY) } })
  const rp = await call(sec, 'POST', `${A}/casos`, { origem: 'SECRETARIA', contexto: 'TRANSFERENCIA', titulo: 'Protocolo com documento crítico', protocoloId: proto.id, refType: 'SecProtocolo', refId: proto.id, documentos: [{ tipo: 'HISTORICO_ESCOLAR', texto: textoHistorico({ nome: 'Thiago Brandão Neves', cpf: cpf1, inst: 'Universidade Internacional do Futuro Brilhante', cod: '9999', curso: 'Odontologia', total: 60, emissao: ymd(-9), assin: true, qr: true, disc: [['Anatomia', 60, 8, 'APROVADO', 2024]] }) }] })
  check('instituição inexistente => CRITICO', rp.json.resultado === 'CRITICO' && por(rp.json.achados, 'INSTITUICAO_INEXISTENTE')[0]?.gravidade === 'CRITICA')
  const bl = await call(sec, 'GET', `${A}/bloqueio?refType=SecProtocolo&refId=${proto.id}`)
  check('consulta de bloqueio informa CRITICO_SEM_DECISAO', bl.json?.bloqueado === true && bl.json?.motivo === 'CRITICO_SEM_DECISAO')
  const st1 = await call(sec, 'POST', `/edu/secretaria/protocolos/${proto.id}/status`, { para: 'DEFERIDO', parecer: 'Documentos conferidos e em ordem.' })
  check('deferir protocolo bloqueado -> 409', st1.status === 409 && /CRÍTICO|Agente de documentos/.test(st1.json?.error || ''), st1.json)
  const st1b = await call(sec, 'POST', `/edu/secretaria/protocolos/${proto.id}/status`, { para: 'INDEFERIDO', parecer: 'Documento de instituição inexistente.' })
  check('indeferir continua permitido', st1b.status === 200)
  // desfazer para testar liberação após decisão
  await prisma.secProtocolo.update({ where: { id: proto.id }, data: { status: 'EM_ANALISE', decisao: null, decisaoMotivo: null, decididoEm: null } })
  // decisão: operadores comuns não podem; precisa reitoria/diretoria e outra pessoa
  check('secretária (não é diretoria) não decide crítico (403)', (await call(sec, 'POST', `${A}/casos/${rp.json.id}/decisao`, { decisao: 'APROVAR_COM_RESSALVA', justificativa: 'Tentativa de liberar sem alçada para decidir.' })).status === 403)
  const rcoord = await call(coord, 'POST', `${A}/casos`, { origem: 'SECRETARIA', titulo: 'Criado pela coordenação', documentos: [{ tipo: 'HISTORICO_ESCOLAR', texto: textoHistorico({ nome: 'Marcos Vilela', cpf: cpf1, inst: 'Faculdade Santa Aurora', cod: '1003', curso: 'Administração', total: 60, emissao: ymd(-9), assin: true, disc: [['Contabilidade', 60, 8, 'APROVADO', 2024]] }) }] })
  check('IES descredenciada => CRITICO', rcoord.json.resultado === 'CRITICO' && por(rcoord.json.achados, 'INSTITUICAO_DESCREDENCIADA').length === 1)
  check('quem enviou não decide o próprio crítico (four-eyes)', (await call(coord, 'POST', `${A}/casos/${rcoord.json.id}/decisao`, { decisao: 'REJEITAR', justificativa: 'Eu mesmo decido o caso que enviei.' })).status === 403)
  check('justificativa de crítico exige 20+ caracteres', (await call(reitor, 'POST', `${A}/casos/${rp.json.id}/decisao`, { decisao: 'REJEITAR', justificativa: 'curta demais.' })).status === 400)
  check('resolver achado crítico exige alçada (403)', (await call(sec, 'POST', `${A}/casos/${rp.json.id}/achados/${rp.json.achados.find((a: any) => a.gravidade === 'CRITICA').id}/resolver`, { nota: 'Resolvido por engano indevido' })).status === 403)
  const decR = await call(reitor, 'POST', `${A}/casos/${rp.json.id}/decisao`, { decisao: 'APROVAR_COM_RESSALVA', justificativa: 'Instituição confirmada por ofício; aprovado com ressalva pela reitoria.' })
  check('reitor registra a decisão e libera o bloqueio', decR.status === 200 && decR.json.status === 'APROVADO' && decR.json.bloqueado === false && decR.json.decididoPorNome)
  check('decisão resolve os achados críticos/altos', decR.json.achados.filter((a: any) => ['CRITICA', 'ALTA'].includes(a.gravidade)).every((a: any) => a.resolvido))
  check('eventos DECISAO e DESBLOQUEIO registrados', decR.json.eventos.some((e: any) => e.tipo === 'DECISAO') && decR.json.eventos.some((e: any) => e.tipo === 'DESBLOQUEIO'))
  check('lembretes críticos concluídos após a decisão', (await prisma.eduReminder.count({ where: { tenantId: T, refType: 'AdcCaso', refId: rp.json.id, status: { in: ['PENDENTE', 'NOTIFICADO', 'ADIADO'] } } })) === 0)
  const st2 = await call(sec, 'POST', `/edu/secretaria/protocolos/${proto.id}/status`, { para: 'DEFERIDO', parecer: 'Deferido após decisão da reitoria.' })
  check('após decisão humana o protocolo pode ser deferido', st2.status === 200, st2.json)
  const aud2 = await prisma.eduAuditEvent.count({ where: { tenantId: T, modulo: 'analise-docs', acao: 'DECISAO_REGISTRADA', refId: rp.json.id } })
  check('auditoria da decisão', aud2 === 1)

  // decisão desfavorável mantém o processo travado
  const proto2 = await prisma.secProtocolo.create({ data: { tenantId: T, numero: `2026/${Math.floor(Math.random() * 900000 + 1000)}`, ano: 2026, seq: Math.floor(Math.random() * 900000 + 1000), tipoId: tipoReq.id, assunto: 'Outra transferência', status: 'EM_ANALISE', prazoEm: new Date(Date.now() + 5 * DAY) } })
  const rp2 = await call(sec, 'POST', `${A}/casos`, { origem: 'SECRETARIA', titulo: 'Rejeitado', protocoloId: proto2.id, refType: 'SecProtocolo', refId: proto2.id, documentos: [{ tipo: 'DIPLOMA', arquivo: { nome: 'diploma.pdf', mime: 'application/pdf', dataUrl: pdfFicticio([`Nome do diplomado: Joana Prado`, `CPF: ${fmtCpf(cpf2)}`, 'Instituição: Universidade Federal do Vale Azul', 'Código e-MEC: 1001', 'Curso: Farmácia', `Data de conclusão: ${br(ymd(-300))}`, `Data de emissão: ${br(ymd(-5))}`, 'Diploma nº ZZ-1', 'QR Code de verificação: presente'], { producer: 'Adobe Photoshop', criado: ymd(-500), modificado: ymd(-4) }) }, metadados: { camposSobrepostos: true } }] })
  check('PDF com Photoshop + criado antes da emissão + sobreposição => adulteração CRITICA', por(rp2.json.achados, 'INDICIO_ADULTERACAO')[0]?.gravidade === 'CRITICA' && rp2.json.resultado === 'CRITICO')
  check('metadados do PDF aparecem no documento', rp2.json.documentos[0].metadados.producer === 'Adobe Photoshop')
  await call(admin, 'POST', `${A}/casos/${rp2.json.id}/decisao`, { decisao: 'REJEITAR', justificativa: 'Falsidade confirmada na conferência com a instituição de origem.' })
  const st3 = await call(sec, 'POST', `/edu/secretaria/protocolos/${proto2.id}/status`, { para: 'CONCLUIDO', parecer: 'Tentando concluir mesmo assim.' })
  check('decisão REJEITAR mantém o processo bloqueado para conclusão (409)', st3.status === 409, st3.json)
  check('bloqueio por decisão desfavorável é informado', (await call(sec, 'GET', `${A}/bloqueio?refType=SecProtocolo&refId=${proto2.id}`)).json?.motivo === 'DECISAO_DESFAVORAVEL')

  // bloqueios em outros módulos
  const pay = await prisma.accountPayable.create({ data: { tenantId: T, descricao: 'Fornecedor com NF suspeita', valor: 1000, dataVencimento: new Date(Date.now() + 5 * DAY) } })
  const rf = await call(fin, 'POST', `${A}/casos`, { origem: 'FINANCEIRO', contexto: 'NOTA_FISCAL', titulo: 'NF suspeita', refType: 'AccountPayable', refId: pay.id, documentos: [{ tipo: 'NOTA_FISCAL', arquivo: { nome: 'nf.pdf', mime: 'application/pdf', dataUrl: pdfFicticio(['Emitente: Papelaria Central Eireli', 'CNPJ: 11.222.333/0001-81', 'Nota fiscal nº 9981', 'Valor total: R$ 48.900,00', `Data de emissão: ${br(ymd(-20))}`], { producer: 'iLovePDF', creator: 'Canva', criado: ymd(-60), modificado: ymd(-2) }) }, metadados: { camposSobrepostos: true } }] })
  check('financeiro: NF adulterada => CRITICO', rf.status === 201 && rf.json.resultado === 'CRITICO')
  const p1 = await call(fin, 'POST', `/edu/financeiro/payables/${pay.id}/pay`, { formaPagamento: 'PIX' })
  check('pagamento da conta bloqueado (409)', p1.status === 409 && /Agente de documentos/.test(p1.json?.error || ''), p1.json)
  check('diretoria do financeiro (FINANCE) é avisada', (await prisma.eduReminder.count({ where: { tenantId: T, refId: rf.json.id, assigneeRole: 'FINANCE', dedupeKey: { startsWith: 'adc:crit:' } } })) === 1)
  check('financeiro não decide o próprio crítico (four-eyes)', (await call(fin, 'POST', `${A}/casos/${rf.json.id}/decisao`, { decisao: 'APROVAR', justificativa: 'Tentando aprovar o que eu mesmo enviei.' })).status === 403)
  await call(reitor, 'POST', `${A}/casos/${rf.json.id}/decisao`, { decisao: 'APROVAR_COM_RESSALVA', justificativa: 'Nota original conferida no portal da prefeitura; liberado.' })
  const p2 = await call(fin, 'POST', `/edu/financeiro/payables/${pay.id}/pay`, { formaPagamento: 'PIX' })
  check('pagamento liberado após decisão humana', p2.status === 200, p2.json)

  const tit = await prisma.tesTitulo.create({ data: { tenantId: T, numero: tx('TIT'), descricao: 'Serviço gráfico', fornecedor: 'Gráfica Arco-Íris', valorBruto: 500, valorLiquido: 500, vencimento: new Date(Date.now() + 5 * DAY), criadoPorId: fin.id, status: 'CONFERIDO' } as any })
  const rt = await call(fin, 'POST', `${A}/casos`, { origem: 'FINANCEIRO', contexto: 'NOTA_FISCAL', titulo: 'NF do título com CNPJ do emitente em pessoa diferente', refType: 'TesTitulo', refId: tit.id, documentos: [{ tipo: 'NOTA_FISCAL', texto: 'Emitente: Gráfica Arco-Íris\nCNPJ: 11.222.333/0001-81\nNota fiscal nº 77\nValor total: R$ 500,00\nData de emissão: ' + br(ymd(-2)), metadados: { assinaturaPresente: true, assinaturaValida: false } }] })
  check('financeiro (tesouraria): documento com assinatura inválida => CRITICO', rt.status === 201 && rt.json.resultado === 'CRITICO')
  const au1 = await call(admin, 'POST', `/edu/tesouraria/titulos/${tit.id}/autorizar`, {})
  check('autorização do título da tesouraria bloqueada (409)', au1.status === 409 && /Agente de documentos/.test(au1.json?.error || ''), au1.json)
  check('baixa do título da tesouraria bloqueada (409)', (await call(admin, 'POST', `/edu/tesouraria/titulos/${tit.id}/baixa`, {})).status === 409)
  await call(reitor, 'POST', `${A}/casos/${rt.json.id}/decisao`, { decisao: 'REJEITAR', justificativa: 'Assinatura inválida confirmada: nota devolvida ao fornecedor.' })
  check('decisão REJEITAR mantém o título bloqueado', (await call(admin, 'POST', `/edu/tesouraria/titulos/${tit.id}/autorizar`, {})).status === 409)

  const contrato = await prisma.jurContrato.create({ data: { tenantId: T, codigo: tx('CT'), tipo: 'OUTRO', objeto: 'Serviço de teste', contraparteNome: 'Empresa Teste', vigenciaInicio: new Date(), vigenciaFim: new Date(Date.now() + 200 * DAY) } })
  const rj = await call(legal, 'POST', `${A}/casos`, { origem: 'JURIDICO', contexto: 'CONTRATO', titulo: 'Contrato com assinatura inválida', refType: 'JurContrato', refId: contrato.id, documentos: [{ tipo: 'CONTRATO', texto: `Contratante: SUA INSTITUIÇÃO\nContratada: Empresa Teste\nInício da vigência: ${br(ymd(0))}\nFim da vigência: ${br(ymd(200))}\nValor: R$ 1.000,00\nAssinatura digital: presente`, metadados: { assinaturaPresente: true, assinaturaValida: false } }] })
  check('jurídico: assinatura digital inválida => CRITICO', rj.json.resultado === 'CRITICO')
  const at1 = await call(legal, 'POST', `/edu/juridico/contratos/${contrato.id}/ativar`)
  check('ativação do contrato bloqueada (409)', at1.status === 409 && /Agente de documentos/.test(at1.json?.error || ''), at1.json)
  await call(admin, 'POST', `${A}/casos/${rj.json.id}/decisao`, { decisao: 'APROVAR_COM_RESSALVA', justificativa: 'Certificado digital verificado manualmente no validador oficial.' })
  check('contrato pode ser ativado após a decisão', (await call(legal, 'POST', `/edu/juridico/contratos/${contrato.id}/ativar`)).status === 200)

  // ---------------------------------------------------------------- instituições (MEC/secretarias) simuladas
  secao('Veracidade de instituição (provedor simulado)')
  const q = async (qs: string) => (await call(sec, 'GET', `${A}/instituicoes-consulta?${qs}`)).json
  const i1 = await q('tipo=IES&codigo=1001&nome=Universidade%20Federal%20do%20Vale%20Azul&curso=Odontologia')
  check('IES regular encontrada, curso reconhecido, resultado SIMULADO', i1.encontrada && i1.situacao === 'REGULAR' && i1.cursoReconhecido === true && i1.simulada === true && /SIMULADO/.test(i1.aviso))
  check('IES descredenciada', (await q('tipo=IES&codigo=1003')).situacao === 'DESCREDENCIADA')
  check('IES inexistente', (await q('tipo=IES&codigo=9999&nome=Universidade%20Fantasma%20do%20Nada')).encontrada === false)
  check('curso não reconhecido', (await q('tipo=IES&codigo=1002&curso=Medicina%20Veterin%C3%A1ria')).cursoReconhecido === false)
  check('busca por nome aproximado', (await q('tipo=IES&nome=Centro%20Universitario%20Horizonte')).instituicao?.codigo === '1002')
  check('IES em extinção e suspensa', (await q('tipo=IES&codigo=1004')).situacao === 'EM_EXTINCAO' && (await q('tipo=IES&codigo=1006')).situacao === 'SUSPENSA')
  const e1 = await q('tipo=ESCOLA&codigo=35000123')
  check('escola regular com secretaria estadual', e1.encontrada && e1.situacao === 'REGULAR' && /Secretaria/.test(e1.instituicao.secretariaEstadual))
  check('escola descredenciada e escola inexistente', (await q('tipo=ESCOLA&codigo=35000999')).situacao === 'DESCREDENCIADA' && (await q('tipo=ESCOLA&codigo=11111111')).encontrada === false)
  check('consulta sem código nem nome -> 400', (await call(sec, 'GET', `${A}/instituicoes-consulta?tipo=IES`)).status === 400)
  const lista = (await call(sec, 'GET', `${A}/instituicoes?pageSize=100`)).json
  check('base de demonstração listada (fictícia)', lista.total >= 12 && /DEMONSTRACAO/.test(lista.fonte))
  check('operador não altera a base (403)', (await call(sec, 'POST', `${A}/instituicoes`, { tipo: 'IES', codigo: '5555', nome: 'Faculdade Nova', uf: 'SP', situacao: 'REGULAR' })).status === 403)
  const nova = await call(admin, 'POST', `${A}/instituicoes`, { tipo: 'IES', codigo: '5555', nome: 'Faculdade Nova Esperança', uf: 'sp', situacao: 'REGULAR', cursos: [{ nome: 'Odontologia', reconhecido: true }] })
  check('administração cadastra instituição', nova.status === 201 && nova.json.uf === 'SP' && nova.json.fonte === 'MANUAL')
  check('código duplicado -> 409', (await call(admin, 'POST', `${A}/instituicoes`, { tipo: 'IES', codigo: '5555', nome: 'Outra Faculdade', uf: 'SP', situacao: 'REGULAR' })).status === 409)
  check('código inválido -> 400', (await call(admin, 'POST', `${A}/instituicoes`, { tipo: 'IES', codigo: 'abc', nome: 'Faculdade Ruim', uf: 'SP', situacao: 'REGULAR' })).status === 400)
  check('alterar situação para descredenciada reflete na consulta', (await call(admin, 'PATCH', `${A}/instituicoes/${nova.json.id}`, { situacao: 'DESCREDENCIADA' })).status === 200 && (await q('tipo=IES&codigo=5555')).situacao === 'DESCREDENCIADA')
  check('remover instituição', (await call(admin, 'DELETE', `${A}/instituicoes/${nova.json.id}`)).status === 204 && (await q('tipo=IES&codigo=5555')).encontrada === false)
  check('provedor EMEC sem credencial cai no simulado com aviso', (await call(admin, 'PUT', `${A}/config`, { provedor: 'EMEC' })).status === 200 && /não está configurado|DEMONSTRAÇÃO/.test((await call(sec, 'GET', `${A}/instituicoes-consulta?tipo=IES&codigo=1001`)).json.aviso))
  await call(admin, 'PUT', `${A}/config`, { provedor: 'SIMULADO' })
  const rEsc = await call(sec, 'POST', `${A}/casos`, { origem: 'SECRETARIA', contexto: 'MATRICULA', titulo: 'EJA descredenciada', documentos: [{ tipo: 'HISTORICO_ENSINO_MEDIO', texto: `Nome: Wellington Costa Arantes\nEscola: Colégio Atlântico Supletivo Ltda\nCódigo da escola: 35000999\nUF: SP\nNível de ensino: EJA\nData de conclusão: ${br(ymd(-150))}\nData de emissão: ${br(ymd(-20))}\nAssinatura: ausente` }] })
  check('escola de EJA descredenciada => CRITICO + assinatura ausente', rEsc.json.resultado === 'CRITICO' && por(rEsc.json.achados, 'INSTITUICAO_DESCREDENCIADA').length === 1 && por(rEsc.json.achados, 'ASSINATURA_QR_AUSENTE').length === 1)
  check('consulta de escola registrada com provedor', rEsc.json.consultas[0].tipo === 'ESCOLA' && rEsc.json.consultas[0].simulada === true)
  const rExt = await call(sec, 'POST', `${A}/casos`, { origem: 'SECRETARIA', titulo: 'IES em extinção e curso não reconhecido', documentos: [{ tipo: 'HISTORICO_ESCOLAR', texto: textoHistorico({ nome: 'Mariana Peixoto', inst: 'Centro Universitário Horizonte', cod: '1002', curso: 'Medicina Veterinária', total: 60, emissao: ymd(-10), assin: true, disc: [['Anatomia Veterinária', 60, 8, 'APROVADO', 2024]] }) }] })
  check('curso não reconhecido => ALTA (atenção)', por(rExt.json.achados, 'CURSO_NAO_RECONHECIDO')[0]?.gravidade === 'ALTA' && rExt.json.resultado === 'ATENCAO')
  const rCod = await call(sec, 'POST', `${A}/casos`, { origem: 'SECRETARIA', titulo: 'Código de outra IES', documentos: [{ tipo: 'DIPLOMA', texto: `Nome do diplomado: Pedro Lins\nCPF: ${fmtCpf(cpf1)}\nInstituição: Universidade Estadual do Sertão\nCódigo e-MEC: 1002\nCurso: Odontologia\nData de conclusão: ${br(ymd(-200))}\nDiploma nº X-77\nAssinado digitalmente` }] })
  check('nome não confere com o código da IES => ALTA', por(rCod.json.achados, 'INSTITUICAO_CODIGO_DIVERGENTE').length === 1)
  const rSem = await call(sec, 'POST', `${A}/casos`, { origem: 'SECRETARIA', titulo: 'Sem instituição', documentos: [{ tipo: 'DIPLOMA', campos: { nome: 'Fulano Teste', cpf: cpfFicticio(77), curso: 'Odontologia', dataConclusao: ymd(-100), numeroDocumento: 'N-1', assinaturaDigital: true } }] })
  check('instituição não informada => ALTA', por(rSem.json.achados, 'INSTITUICAO_NAO_INFORMADA').length === 1)

  // ---------------------------------------------------------------- duplicidade
  secao('Diploma duplicado e arquivo reaproveitado')
  const dipTxt = (nome: string, cpf: string) => `Nome do diplomado: ${nome}\nCPF: ${fmtCpf(cpf)}\nInstituição: Universidade Federal do Vale Azul\nCódigo e-MEC: 1001\nCurso: Farmácia\nData de conclusão: ${br(ymd(-800))}\nData de emissão: ${br(ymd(-760))}\nDiploma nº UFVA-2024-009911\nQR Code de verificação: presente`
  const cA = cpfFicticio(501), cB = cpfFicticio(502)
  const d1 = await call(sec, 'POST', `${A}/casos`, { origem: 'SECRETARIA', contexto: 'DIPLOMA', titulo: 'Diploma original', documentos: [{ tipo: 'DIPLOMA', texto: dipTxt('Isabela Rocha Medeiros', cA) }] })
  check('primeiro diploma sem duplicidade', por(d1.json.achados, 'DIPLOMA_DUPLICADO').length === 0)
  const d2 = await call(sec, 'POST', `${A}/casos`, { origem: 'SECRETARIA', contexto: 'DIPLOMA', titulo: 'Diploma repetido por outra pessoa', documentos: [{ tipo: 'DIPLOMA', texto: dipTxt('Jéssica Rocha Medeiros', cB) }] })
  check('mesmo diploma em nome de outra pessoa => CRITICA', por(d2.json.achados, 'DIPLOMA_DUPLICADO')[0]?.gravidade === 'CRITICA' && d2.json.resultado === 'CRITICO')
  const d3 = await call(sec, 'POST', `${A}/casos`, { origem: 'SECRETARIA', contexto: 'DIPLOMA', titulo: 'Mesmo diploma, mesmo titular', documentos: [{ tipo: 'DIPLOMA', texto: dipTxt('Isabela Rocha Medeiros', cA) }] })
  check('mesmo diploma do mesmo titular => MEDIA (e CRITICA pela outra pessoa)', por(d3.json.achados, 'DIPLOMA_DUPLICADO').some((a: any) => a.gravidade === 'MEDIA') && por(d3.json.achados, 'DIPLOMA_DUPLICADO').some((a: any) => a.gravidade === 'CRITICA'))
  const arq = { nome: 'rg.txt', mime: 'text/plain', dataUrl: 'data:text/plain;base64,' + Buffer.from(`Nome: Quem Quer\nCPF: ${fmtCpf(cA)}\nData de nascimento: 01/01/1990`).toString('base64') }
  await call(sec, 'POST', `${A}/casos`, { origem: 'SECRETARIA', titulo: 'RG enviado 1', documentos: [{ tipo: 'RG_CPF', arquivo: arq }] })
  const arq2 = await call(sec, 'POST', `${A}/casos`, { origem: 'SECRETARIA', titulo: 'RG enviado 2 por outro CPF', documentos: [{ tipo: 'RG_CPF', arquivo: arq, campos: { cpf: cB } }] })
  check('mesmo arquivo em nome de outro CPF => ARQUIVO_REAPROVEITADO CRITICA', por(arq2.json.achados, 'ARQUIVO_REAPROVEITADO')[0]?.gravidade === 'CRITICA')

  // ---------------------------------------------------------------- LGPD
  secao('LGPD: minimização, log de acesso, cifra e retenção')
  const campos = await call(sec, 'GET', `${A}/casos/${ok1.id}/campos?motivo=Conferir%20identidade%20do%20aluno`)
  check('secretaria vê dados completos com motivo', campos.status === 200 && campos.json.documentos[0].campos.nome === 'Camila Duarte Ferraz' && campos.json.documentos[1].campos.cpf === cpf1)
  check('motivo obrigatório (400)', (await call(sec, 'GET', `${A}/casos/${ok1.id}/campos`)).status === 400)
  check('coordenação (só mascarado) não vê dados completos (403)', (await call(coord, 'GET', `${A}/casos/${ok1.id}/campos?motivo=Teste%20de%20acesso`)).status === 403)
  check('financeiro não acessa caso da secretaria (404)', (await call(fin, 'GET', `${A}/casos/${ok1.id}`)).status === 404)
  await call(sec, 'GET', `${A}/casos/${ok1.id}`)
  const logs = await prisma.lgpAcessoSensivel.findMany({ where: { tenantId: T, recurso: { startsWith: 'analise-docs' }, recursoId: ok1.id } })
  check('acessos registrados em lgpAcessoSensivel (leitura e dados completos)', logs.some((l) => l.acao === 'LEITURA') && logs.some((l) => l.acao === 'LEITURA_COMPLETA' && /identidade/.test(l.motivo || '')))
  const evs = (await call(sec, 'GET', `${A}/casos/${ok1.id}`)).json.eventos
  check('evento ACESSO_DADOS no histórico do caso', evs.some((e: any) => e.tipo === 'ACESSO_DADOS'))
  check('log de auditoria do acesso completo', (await prisma.eduAuditEvent.count({ where: { tenantId: T, acao: 'DADOS_COMPLETOS_CONSULTADOS', refId: ok1.id } })) === 1)
  const listaTxt = JSON.stringify((await call(sec, 'GET', `${A}/casos?pageSize=100`)).json)
  check('listagem nunca traz CPF/dadosCif', !listaTxt.includes(cpf1) && !listaTxt.includes('dadosCif'))
  const edit = await call(sec, 'PATCH', `${A}/casos/${crit.id}/documentos/${crit.documentos[1].id}/campos`, { campos: { nome: 'Rafael Augusto Pinheiro', cpf: cpf1 } })
  check('correção manual de campos reanalisa e remove o conflito de CPF', edit.status === 200 && por(edit.json.achados, 'CONFLITO_CPF').length === 0, edit.json?.achados?.map((a: any) => a.regra))
  check('edição registra evento sem valores', edit.json.eventos.some((e: any) => e.tipo === 'CAMPOS_EDITADOS' && !JSON.stringify(e).includes(cpf1)))
  check('caso continua bloqueado até decisão (mesmo sem conflito)', edit.json.bloqueado === true)

  // retenção
  const cr = await call(sec, 'POST', `${A}/casos`, { origem: 'SECRETARIA', titulo: 'Para retenção', documentos: [docOk('Maria Retenção Lima', cpfFicticio(808))] })
  await call(sec, 'POST', `${A}/casos/${cr.json.id}/decisao`, { decisao: 'APROVAR', justificativa: 'Conforme documento de identidade.' })
  await prisma.adcCaso.update({ where: { id: cr.json.id }, data: { expiraEm: new Date(Date.now() - DAY) } })
  const ret = await call(admin, 'POST', `${A}/retencao/executar`)
  check('retenção apaga dados pessoais cifrados dos casos vencidos', ret.status === 200 && ret.json.apagados >= 1)
  check('dados apagados: banco sem dadosCif e sem nome', (await prisma.adcDocumento.findFirst({ where: { casoId: cr.json.id } }))?.dadosCif === null && (await prisma.adcCaso.findUnique({ where: { id: cr.json.id } }))?.sujeitoNome === null)
  check('dados apagados: campos completos -> 410', (await call(sec, 'GET', `${A}/casos/${cr.json.id}/campos?motivo=Teste%20de%20retencao`)).status === 410)
  check('não reanalisa caso com dados apagados (409)', (await call(sec, 'POST', `${A}/casos/${cr.json.id}/analisar`)).status === 409)
  check('operador não executa retenção (403)', (await call(sec, 'POST', `${A}/retencao/executar`)).status === 403)

  // ---------------------------------------------------------------- isolamento
  secao('Isolamento entre instituições')
  check('tenant B não vê caso do tenant A (404)', (await call(sec2, 'GET', `${A}/casos/${ok1.id}`)).status === 404)
  check('tenant B lista vazio', (await call(sec2, 'GET', `${A}/casos`)).json.total === 0)
  check('tenant B não decide caso do A (404)', (await call(admin2, 'POST', `${A}/casos/${crit.id}/decisao`, { decisao: 'APROVAR', justificativa: 'Tentativa entre instituições.' })).status === 404)
  check('tenant B não vê instituições do A (base própria)', (await call(admin2, 'GET', `${A}/instituicoes`)).json.total >= 12 && (await prisma.adcInstituicao.count({ where: { tenantId: T2 } })) >= 12)
  check('alterar instituição do A pelo B -> 404', (await call(admin2, 'PATCH', `${A}/instituicoes/${(await prisma.adcInstituicao.findFirst({ where: { tenantId: T } }))!.id}`, { situacao: 'SUSPENSA' })).status === 404)
  check('bloqueio do A não afeta protocolo do B', (await call(sec2, 'GET', `${A}/bloqueio?refType=SecProtocolo&refId=${proto.id}`)).json.bloqueado === false)
  check('painel do B vazio', (await call(admin2, 'GET', `${A}/painel`)).json.naFila === 0)

  // ---------------------------------------------------------------- equivalência com a matriz do curso
  secao('Equivalência de disciplinas com a matriz do curso')
  const prog = await prisma.academicProgram.create({ data: { tenantId: T, nome: 'Odontologia ' + tx('e'), modalidade: 'PRESENCIAL', cargaHorariaTotal: 4000 } })
  const mkDisc = (nome: string, ch: number, ementa?: string) => prisma.discipline.create({ data: { tenantId: T, nome, cargaHoraria: ch, ementa } })
  const dAna = await mkDisc('Anatomia Humana', 80, 'Estudo da anatomia sistêmica e topográfica do corpo humano'), dHis = await mkDisc('Histologia e Embriologia', 60), dBio = await mkDisc('Bioquímica Oral', 60), dDe1 = await mkDisc('Dentística I', 80), dDe2 = await mkDisc('Dentística II', 80)
  const matriz = await prisma.acaMatriz.create({ data: { tenantId: T, programId: prog.id, nome: 'Matriz 2026', versao: tx('v'), status: 'VIGENTE', cargaHorariaTotal: 360 } })
  const per = await prisma.acaMatrizPeriodo.create({ data: { tenantId: T, matrizId: matriz.id, ordem: 1, rotulo: '1º semestre' } })
  const itens: Record<string, string> = {}
  for (const d of [dAna, dHis, dBio, dDe1, dDe2]) itens[d.id] = (await prisma.acaMatrizItem.create({ data: { tenantId: T, matrizId: matriz.id, periodoId: per.id, disciplineId: d.id, cargaHoraria: d.cargaHoraria } })).id
  await prisma.acaPreRequisito.create({ data: { tenantId: T, matrizId: matriz.id, itemId: itens[dDe2.id], requisitoItemId: itens[dDe1.id], tipo: 'PRE' } })
  const ano = new Date().getFullYear()
  const stu = await prisma.student.findFirst({ where: { tenantId: T } })
  const hist = textoHistorico({ nome: stu!.nomeCompleto, inst: 'Universidade Federal do Vale Azul', cod: '1001', curso: 'Odontologia', total: 360, emissao: ymd(-10), assin: true, qr: true, disc: [['Anatomia Humana', 80, 8.5, 'APROVADO', ano - 2], ['Histologia', 40, 7, 'APROVADO', ano - 2], ['Bioquímica Oral', 60, 4, 'REPROVADO', ano - 2], ['Dentística II', 80, 9, 'APROVADO', ano - 15], ['Cálculo Diferencial', 60, 8, 'APROVADO', ano - 2]] })
  const sim = await call(sec, 'POST', `${A}/equivalencias/simular`, { programId: prog.id, studentId: stu!.id, texto: hist })
  check('simulação usa a matriz vigente do curso', sim.status === 200 && sim.json.matrizComDisciplinas === 5 && sim.json.sugestoes.length === 5, sim.json)
  const sg = (n: string) => sim.json.sugestoes.find((s: any) => s.origem === n)
  check('simulação: equivalência plena', sg('Anatomia Humana').sugestao === 'EQUIVALENCIA' && sg('Anatomia Humana').destino === 'Anatomia Humana')
  check('simulação: dispensa parcial por carga', sg('Histologia').sugestao === 'DISPENSA_PARCIAL')
  check('simulação: reprovação bloqueia aproveitamento', sg('Bioquímica Oral').sugestao === 'NAO_EQUIVALENTE' && sg('Bioquímica Oral').avisos.some((a: any) => a.tipo === 'REPROVACAO'))
  check('simulação: prazo de validade e pré-requisito da matriz', sg('Dentística II').avisos.some((a: any) => a.tipo === 'PRAZO_VALIDADE') && sg('Dentística II').avisos.some((a: any) => a.tipo === 'PRE_REQUISITO'))
  check('simulação: disciplina sem correspondente', sg('Cálculo Diferencial').destino === null)
  check('simulação sem disciplinas -> 400', (await call(sec, 'POST', `${A}/equivalencias/simular`, { programId: prog.id, texto: 'nada' })).status === 400)
  check('simulação com curso de outro tenant -> 400', (await call(sec2, 'POST', `${A}/equivalencias/simular`, { programId: prog.id, texto: hist })).status === 400)
  await call(admin, 'PUT', `${A}/config`, { percentualAproveitamento: 40 })
  check('percentual configurável: com 40% a Histologia vira equivalência', (await call(sec, 'POST', `${A}/equivalencias/simular`, { programId: prog.id, texto: hist })).json.sugestoes.find((s: any) => s.origem === 'Histologia').sugestao === 'EQUIVALENCIA')
  await call(admin, 'PUT', `${A}/config`, { percentualAproveitamento: 75 })
  const reqv = await call(sec, 'POST', `${A}/casos`, { origem: 'SECRETARIA', contexto: 'EQUIVALENCIA', titulo: 'Equivalência Odontologia', programId: prog.id, studentId: stu!.id, documentos: [{ tipo: 'HISTORICO_ESCOLAR', texto: hist }] })
  check('caso de equivalência grava as sugestões', reqv.status === 201 && reqv.json.equivalencias.length === 5)
  check('avisos de conflito viram achados (reprovação, prazo, pré-requisito)', ['EQUIV_REPROVACAO', 'EQUIV_PRAZO_VALIDADE', 'EQUIV_PRE_REQUISITO'].every((r) => por(reqv.json.achados, r).length === 1))
  const eqA = reqv.json.equivalencias.find((e: any) => e.origemDisciplina === 'Anatomia Humana'), eqB = reqv.json.equivalencias.find((e: any) => e.origemDisciplina === 'Bioquímica Oral'), eqD = reqv.json.equivalencias.find((e: any) => e.origemDisciplina === 'Dentística II')
  check('aceitar equivalência plena', (await call(sec, 'POST', `${A}/casos/${reqv.json.id}/equivalencias/${eqA.id}/decisao`, { decisao: 'ACEITA' })).status === 200)
  check('não aceita NAO_EQUIVALENTE (409)', (await call(sec, 'POST', `${A}/casos/${reqv.json.id}/equivalencias/${eqB.id}/decisao`, { decisao: 'ACEITA' })).status === 409)
  check('aceitar com avisos ALTA exige justificativa (400)', (await call(sec, 'POST', `${A}/casos/${reqv.json.id}/equivalencias/${eqD.id}/decisao`, { decisao: 'ACEITA' })).status === 400)
  check('aceitar com justificativa', (await call(sec, 'POST', `${A}/casos/${reqv.json.id}/equivalencias/${eqD.id}/decisao`, { decisao: 'ACEITA', nota: 'Parecer do colegiado anexado ao protocolo.' })).status === 200)
  const reanalise = await call(sec, 'POST', `${A}/casos/${reqv.json.id}/analisar`)
  check('reanálise preserva decisões de equivalência', reanalise.json.equivalencias.find((e: any) => e.origemDisciplina === 'Anatomia Humana').decisao === 'ACEITA')
  check('equivalência decidida registrada no histórico', reanalise.json.eventos.some((e: any) => e.tipo === 'EQUIVALENCIA_DECIDIDA'))
  const eqReg = await prisma.acaEquivalencia.create({ data: { tenantId: T, disciplineId: dHis.id, equivalenteId: (await mkDisc('Biologia Tecidual', 60)).id, percentual: 100 } })
  const simB = await call(sec, 'POST', `${A}/equivalencias/simular`, { programId: prog.id, disciplinas: [{ nome: 'Biologia Tecidual', cargaHoraria: 60, nota: 8, situacao: 'APROVADO', ano }] })
  check('reaproveita equivalências já cadastradas em academico2', simB.json.sugestoes[0].destino === 'Histologia e Embriologia' && simB.json.sugestoes[0].sugestao === 'EQUIVALENCIA' && !!eqReg.id)
  const semMatriz = await prisma.academicProgram.create({ data: { tenantId: T, nome: 'Curso sem matriz ' + tx('s'), modalidade: 'EAD', cargaHorariaTotal: 100 } })
  const rsm = await call(sec, 'POST', `${A}/casos`, { origem: 'SECRETARIA', titulo: 'Sem matriz', programId: semMatriz.id, documentos: [{ tipo: 'HISTORICO_ESCOLAR', texto: hist }] })
  check('curso sem matriz gera aviso (não falha)', rsm.status === 201 && por(rsm.json.achados, 'MATRIZ_SEM_DISCIPLINAS').length === 1)

  // ---------------------------------------------------------------- fluxos auxiliares
  secao('Fila, atribuição, comentários, achados e documentos extras')
  const rx = await call(sec, 'POST', `${A}/casos`, { origem: 'SECRETARIA', titulo: 'Declaração sem assinatura', documentos: [{ tipo: 'DECLARACAO', texto: `Nome: Paulo Henrique\nInstituição: Universidade do Planalto Central\nData de emissão: ${br(ymd(-3))}`, campos: { nivelEnsino: 'SUPERIOR', codigoIes: '1007' } }] })
  check('declaração sem assinatura => ATENCAO', rx.json.resultado === 'ATENCAO' && por(rx.json.achados, 'ASSINATURA_QR_AUSENTE').length === 1)
  check('atribuir revisor', (await call(sec, 'POST', `${A}/casos/${rx.json.id}/atribuir`, { responsavelId: coord.id })).json.responsavelNome != null)
  check('atribuir a usuário inexistente -> 400', (await call(sec, 'POST', `${A}/casos/${rx.json.id}/atribuir`, { responsavelId: 'nao-existe' })).status === 400)
  check('revisor atribuído é notificado', (await prisma.eduNotification.count({ where: { tenantId: T, userId: coord.id, refId: rx.json.id } })) === 1)
  check('comentário', (await call(sec, 'POST', `${A}/casos/${rx.json.id}/comentarios`, { texto: 'Solicitei a via assinada ao aluno.' })).status === 201)
  const rx2 = await call(sec, 'POST', `${A}/casos/${rx.json.id}/documentos`, { tipo: 'RG_CPF', texto: `Nome: Paulo Henrique\nCPF: ${fmtCpf(cpf1)}\nData de nascimento: 01/01/1995` })
  check('adicionar documento ao caso reanalisa', rx2.status === 201 && rx2.json.documentos.length === 2 && rx2.json.eventos.some((e: any) => e.tipo === 'DOCUMENTO_ADICIONADO'))
  const ab = rx2.json.achados.find((a: any) => a.regra === 'ASSINATURA_QR_AUSENTE')
  check('resolver achado exige nota (400)', (await call(sec, 'POST', `${A}/casos/${rx.json.id}/achados/${ab.id}/resolver`, { nota: 'curta' })).status === 400)
  const rs = await call(sec, 'POST', `${A}/casos/${rx.json.id}/achados/${ab.id}/resolver`, { nota: 'Via assinada recebida por e-mail institucional.' })
  check('resolver achado recalcula resultado', rs.status === 200 && rs.json.achados.find((a: any) => a.id === ab.id).resolvido === true && rs.json.score < rx2.json.score)
  check('achado resolvido sobrevive à reanálise', (await call(sec, 'POST', `${A}/casos/${rx.json.id}/analisar`)).json.achados.find((a: any) => a.regra === 'ASSINATURA_QR_AUSENTE')?.resolvido === true)
  const ab2 = (await call(sec, 'GET', `${A}/casos/${rx.json.id}`)).json.achados.find((a: any) => a.regra === 'ASSINATURA_QR_AUSENTE')
  check('resolver duas vezes -> 409', (await call(sec, 'POST', `${A}/casos/${rx.json.id}/achados/${ab2.id}/resolver`, { nota: 'Resolvendo novamente o mesmo.' })).status === 409)
  check('solicitar novo documento', (await call(sec, 'POST', `${A}/casos/${rx.json.id}/decisao`, { decisao: 'SOLICITAR_NOVO_DOCUMENTO', justificativa: 'Enviar histórico atualizado e assinado.' })).json.status === 'DOCUMENTO_SOLICITADO')
  const png = await call(sec, 'POST', `${A}/casos`, { origem: 'SECRETARIA', titulo: 'Imagem sem texto', documentos: [{ tipo: 'RG_CPF', arquivo: { nome: 'rg.png', mime: 'image/png', base64: 'iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR42mNkYPhfDwAChwGA60e6kgAAAABJRU5ErkJggg==' } }] })
  check('imagem sem texto => EXTRACAO_VAZIA (sem OCR) e modo SEM_TEXTO', por(png.json.achados, 'EXTRACAO_VAZIA').length === 1 && png.json.documentos[0].modoExtracao === 'SEM_TEXTO')
  const png2 = await call(sec, 'PATCH', `${A}/casos/${png.json.id}/documentos/${png.json.documentos[0].id}/campos`, { campos: { nome: 'Digitado Manualmente', cpf: cpfFicticio(909), dataNascimento: '1990-05-05' } })
  check('digitação manual dos campos resolve a extração vazia', png2.status === 200 && por(png2.json.achados, 'EXTRACAO_VAZIA').length === 0 && png2.json.documentos[0].modoExtracao === 'CAMPOS')
  check('caso decidido não aceita edição de campos (409)', (await call(sec, 'PATCH', `${A}/casos/${ok1.id}/documentos/${ok1.documentos[0].id}/campos`, { campos: { nome: 'Alterado Depois' } })).status === 409)

  // protocolo -> "Analisar com o agente"
  const proto3 = await prisma.secProtocolo.create({ data: { tenantId: T, numero: `2026/${Math.floor(Math.random() * 900000 + 1000)}`, ano: 2026, seq: Math.floor(Math.random() * 900000 + 1000), tipoId: tipoReq.id, assunto: 'Transferência externa', status: 'EM_ANALISE', prazoEm: new Date(Date.now() + 5 * DAY) } })
  await prisma.secAnexo.create({ data: { tenantId: T, protocoloId: proto3.id, nome: 'historico-escolar.pdf', mime: 'application/pdf', dataUrl: pdfFicticio(textoHistorico({ nome: 'Aluno de Protocolo', cpf: cpfFicticio(606), inst: 'Universidade Federal do Vale Azul', cod: '1001', curso: 'Odontologia', total: 60, emissao: ymd(-10), assin: true, disc: [['Anatomia', 60, 8, 'APROVADO', 2024]] }).split('\n'), { producer: 'Microsoft Word' }) } })
  await prisma.secAnexo.create({ data: { tenantId: T, protocoloId: proto3.id, nome: 'rg-frente.jpg', mime: 'image/jpeg', url: 'https://exemplo.com/rg.jpg' } })
  const dp = await call(sec, 'POST', `${A}/casos/de-protocolo`, { protocoloId: proto3.id })
  check('"Analisar com o agente" a partir do protocolo', dp.status === 201 && dp.json.documentos.length === 2 && dp.json.refType === 'SecProtocolo' && dp.json.protocoloId === proto3.id)
  check('contexto inferido do tipo do protocolo e tipos dos anexos', dp.json.contexto === 'TRANSFERENCIA' && dp.json.documentos.map((d: any) => d.tipo).sort().join() === 'HISTORICO_ESCOLAR,RG_CPF')
  check('protocolo sem anexos -> 422', (await call(sec, 'POST', `${A}/casos/de-protocolo`, { protocoloId: proto.id })).status === 422)
  check('protocolo de outro tenant -> 404', (await call(sec2, 'POST', `${A}/casos/de-protocolo`, { protocoloId: proto3.id })).status === 404)
  check('financeiro não usa o atalho da secretaria (403)', (await call(fin, 'POST', `${A}/casos/de-protocolo`, { protocoloId: proto3.id })).status === 403)

  // ---------------------------------------------------------------- listagem, painel e laudo
  secao('Fila de revisão, painel, SLA e laudo')
  const fila = await call(sec, 'GET', `${A}/casos?fila=true&pageSize=100`)
  check('fila só traz casos em revisão', fila.status === 200 && fila.json.items.length > 0 && fila.json.items.every((c: any) => ['EM_FILA', 'EM_REVISAO'].includes(c.status)))
  check('fila priorizada: bloqueados/críticos primeiro', fila.json.items[0].bloqueado === true)
  check('filtro por resultado CRITICO', (await call(sec, 'GET', `${A}/casos?resultado=CRITICO&pageSize=100`)).json.items.every((c: any) => c.resultado === 'CRITICO'))
  check('filtro bloqueado=true', (await call(sec, 'GET', `${A}/casos?bloqueado=true`)).json.items.every((c: any) => c.bloqueado === true))
  check('busca por código', (await call(sec, 'GET', `${A}/casos?q=${ok1.codigo}`)).json.items.length === 1)
  check('item da lista traz documentos e achados abertos', typeof fila.json.items[0].documentos === 'number' && typeof fila.json.items[0].achadosAbertos === 'number')
  check('filtro de origem proibido -> 403', (await call(sec, 'GET', `${A}/casos?origem=FINANCEIRO`)).status === 403)
  check('financeiro só lista casos do FINANCEIRO', (await call(fin, 'GET', `${A}/casos?pageSize=100`)).json.items.every((c: any) => c.origem === 'FINANCEIRO'))
  check('reitoria vê todas as origens', new Set((await call(reitor, 'GET', `${A}/casos?pageSize=200`)).json.items.map((c: any) => c.origem)).size >= 3)
  await prisma.adcCaso.update({ where: { id: dp.json.id }, data: { slaEm: new Date(Date.now() - 3_600_000) } })
  check('filtro de atrasados (SLA vencido)', (await call(sec, 'GET', `${A}/casos?atrasados=true`)).json.items.some((c: any) => c.id === dp.json.id && c.atrasado === true))
  const painel = (await call(sec, 'GET', `${A}/painel`)).json
  check('painel: fila, críticos, bloqueados e atrasados', painel.naFila > 0 && painel.criticosAbertos > 0 && painel.bloqueados > 0 && painel.atrasados >= 1)
  check('painel: decididos, tempo médio e % no prazo', painel.decididos30d > 0 && painel.tempoMedioHoras !== null && painel.noPrazoPct !== null)
  check('painel: série de 30 dias e achados frequentes', painel.serie.length === 30 && painel.serie.some((s: any) => s.criados > 0) && painel.achadosFrequentes.length > 0)
  check('painel declara provedor simulado', painel.provedor.simulado === true)
  check('painel por perfil: financeiro vê só o seu setor', Object.keys((await call(fin, 'GET', `${A}/painel`)).json.filaPorOrigem).every((k) => k === 'FINANCEIRO'))
  const laudo = await call(sec, 'GET', `${A}/casos/${crit.id}/laudo`)
  check('laudo HTML imprimível com achados e aviso', laudo.status === 200 && /Laudo do Agente/.test(laudo.text) && /CONFLITO_CPF|INSTITUICAO|Conflito/.test(laudo.text) && /não substitui perícia/.test(laudo.text))
  check('laudo sem dados pessoais completos', !laudo.text.includes(cpf1) && !laudo.text.includes(cpf2) && !laudo.text.includes('Rafael Augusto'))
  check('laudo de caso de outro setor -> 404', (await call(fin, 'GET', `${A}/casos/${crit.id}/laudo`)).status === 404)

  // ---------------------------------------------------------------- configuração
  secao('Configuração')
  check('qualquer operador lê a configuração', (await call(sec, 'GET', `${A}/config`)).json.percentualAproveitamento === 75)
  check('operador não altera a configuração (403)', (await call(sec, 'PUT', `${A}/config`, { slaHoras: 10 })).status === 403)
  check('valor fora do limite -> 400', (await call(admin, 'PUT', `${A}/config`, { percentualAproveitamento: 5 })).status === 400)
  check('papel inválido de diretoria -> 400', (await call(admin, 'PUT', `${A}/config`, { diretoriaSecretaria: 'PORTEIRO' })).status === 400)
  const cf = await call(admin, 'PUT', `${A}/config`, { diretoriaSecretaria: 'SECRETARY', slaCriticoHoras: 2 })
  check('administração altera a diretoria e o SLA crítico', cf.status === 200 && cf.json.diretoriaSecretaria === 'SECRETARY' && cf.json.slaCriticoHoras === 2)
  const dr = await call(sec, 'POST', `${A}/casos`, { origem: 'SECRETARIA', titulo: 'Crítico com diretoria alterada', documentos: [{ tipo: 'HISTORICO_ESCOLAR', texto: textoHistorico({ nome: 'Zeca Teste', inst: 'Faculdade Fantasma Inexistente', cod: '8888', curso: 'Odontologia', total: 60, emissao: ymd(-9), assin: true, disc: [['Anatomia', 60, 8, 'APROVADO', 2024]] }) }] })
  check('diretoria configurável recebe o aviso crítico', (await prisma.eduReminder.count({ where: { tenantId: T, refId: dr.json.id, assigneeRole: 'SECRETARY', dedupeKey: { startsWith: 'adc:crit:' } } })) === 1)
  check('SLA crítico configurável', Math.abs(new Date(dr.json.slaEm).getTime() - (new Date(dr.json.createdAt).getTime() + 2 * 3_600_000)) < 5000)
  await call(admin, 'PUT', `${A}/config`, { diretoriaSecretaria: 'COORDINATOR', slaCriticoHoras: 4 })

  // ---------------------------------------------------------------- seed de demonstração
  secao('Seed de demonstração')
  const apiAdmin = async (method: string, path: string, body?: any) => {
    const r = await fetch(baseUrl + path, { method, headers: { Authorization: `Bearer ${admin.token}`, 'Content-Type': 'application/json' }, body: body !== undefined ? JSON.stringify(body) : undefined })
    const t = await r.text(); let j: any = null; try { j = JSON.parse(t) } catch { /* texto */ }
    if (!r.ok) { seedFalhas.push(`${method} ${path} -> ${r.status} ${t.slice(0, 160)}`); return null }
    return j
  }
  const seedFalhas: string[] = []
  const mk = async (email: string, _pw: string, firstName: string, lastName: string, role: string) => {
    const ex = await prisma.user.findFirst({ where: { tenantId: T, email: { startsWith: role.toLowerCase() } } })
    return ex ?? prisma.user.create({ data: { clinicId: t1.clinic.id, tenantId: T, email: `${role.toLowerCase()}.seed.${Math.random().toString(36).slice(2, 6)}@q.com`, password: 'x', firstName, lastName, role } as any })
  }
  const antes = await prisma.adcCaso.count({ where: { tenantId: T } })
  const S = await seedAnaliseDocs(apiAdmin, { tenantId: T, failures: seedFalhas, mk })
  const novos = (await prisma.adcCaso.count({ where: { tenantId: T } })) - antes
  check('seed sem falhas', seedFalhas.length === 0, seedFalhas)
  check('seed cria ≈20 casos', novos >= 20, novos)
  const cs = await prisma.adcCaso.findMany({ where: { tenantId: T }, orderBy: { createdAt: 'desc' }, take: novos })
  check('seed cobre os resultados OK, ATENCAO e CRITICO', ['OK', 'ATENCAO', 'CRITICO'].every((r) => cs.some((c) => c.resultado === r)))
  check('seed cobre os 3 setores', ['SECRETARIA', 'FINANCEIRO', 'JURIDICO'].every((o) => cs.some((c) => c.origem === o)))
  check('seed: conformes aprovados e falso rejeitado', S.ok1?.id && (await prisma.adcCaso.findUnique({ where: { id: S.ok1.id } }))?.status === 'APROVADO' && (await prisma.adcCaso.findUnique({ where: { id: S.falso1.id } }))?.decisao === 'REJEITAR')
  check('seed deixa críticos em aberto bloqueando processos', cs.filter((c) => c.bloqueado).length >= 5)
  const sf = await prisma.adcAchado.findMany({ where: { casoId: S.falso1.id } })
  check('seed: PDF falso detectado por metadados', sf.some((a) => a.regra === 'INDICIO_ADULTERACAO' && a.gravidade === 'CRITICA'))
  check('seed: diploma duplicado detectado', sf.length > 0 && (await prisma.adcAchado.count({ where: { casoId: S.dip2.id, regra: 'DIPLOMA_DUPLICADO', gravidade: 'CRITICA' } })) >= 1)
  check('seed: equivalências geradas com o currículo existente', S.equiv1 ? (await prisma.adcEquivalenciaSug.count({ where: { casoId: S.equiv1.id } })) >= 1 : true)
  check('seed é idempotente em estrutura (nova execução não quebra)', (await seedAnaliseDocs(apiAdmin, { tenantId: T, failures: seedFalhas, mk })).casos.length >= 20 && seedFalhas.length === 0, seedFalhas)

  summary()
  await close()
  process.exit(fails.length ? 1 : 0)
}

main().catch(async (e) => { console.error(e); process.exit(1) })
